<template><section class="max-w-2xl"><h2 class="text-2xl font-bold mb-6">Chi tiết thông báo</h2><p v-if="error" class="text-error">{{error}}</p><p v-else-if="!item" class="text-gray-400">Đang tải…</p><article v-else class="rounded bg-white/5 p-6"><h3 class="text-xl font-semibold">{{item.title}}</h3><p class="mt-4 text-gray-300 whitespace-pre-wrap">{{item.content}}</p><p class="mt-5 text-sm text-gray-400">{{format(item.createdAt)}}</p></article></section></template><script setup>import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import{adminApi}from'../../api/adminService';const route=useRoute(),item=ref(null),error=ref('');const format=v=>v?new Date(v).toLocaleString('vi-VN'):'';onMounted(async()=>{try{item.value=(await adminApi.notification(route.params.id)).data;if(!item.value.isRead)item.value=(await adminApi.markRead(route.params.id)).data}catch(e){error.value='Không thể tải thông báo.'}})</script>
